"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_en"]=window.LC_CHUNKS["university_physics_en"]||{};window.LC_CHUNKS["university_physics_en"][43]={"university_physics_en:M43-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M43-L1 – Research Questions, Hypotheses and Testable Model Predictions<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M31: numerical modelling; M39:\nrelaxation processes; M42-L6: research documentation. <a\nhref=\"index.html?course=university_physics&amp;module=M42&amp;lesson=L6&amp;syslang=en&amp;doclang=en&amp;theme=light\">Previous module<\/a>.<\/p>\n<p><strong>Learning objective:<\/strong> Turn a physical assumption into\na quantitatively specified, potentially refutable prediction.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>A research question specifies a measurand, physical system,\nmanipulated variable and relevant timescale. A testable hypothesis does\nnot merely predict that a value decreases: it specifies a model and an\nobservable consequence. <strong>Falsifiability<\/strong> does not\nguarantee truth; discrepancies may result from measurement error,\nincorrect initial conditions or model inadequacy. Alternative models and\ndecision criteria should be documented beforehand.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>For linear relaxation towards a fixed equilibrium\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><annotation encoding=\"application/x-tex\">y_\\infty<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>y<\/mi><mi>/<\/mi><mi>d<\/mi><mi>t<\/mi><mo>=<\/mo><mi>−<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">dy/dt=-(y-y_\\infty)/\\tau<\/annotation><\/semantics><\/math>.\nSeparation of variables yields\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(t)=y_\\infty+(y_0-y_\\infty)e^{-t/\\tau}<\/annotation><\/semantics><\/math>.\nThe time constant\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>τ<\/mi><annotation encoding=\"application/x-tex\">\\tau<\/annotation><\/semantics><\/math>\nis the time after which the initial departure from equilibrium has\nfallen to\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">e^{-1}<\/annotation><\/semantics><\/math>;\nit is not the half-life\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau\\ln 2<\/annotation><\/semantics><\/math>.\nThis model assumes constant parameters and one dominant relaxation\ntimescale.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y(t)=y_\\infty+(y_0-y_\\infty)e^{-t/\\tau},\\qquad t_{1/2}=\\tau\\ln2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>For a <strong>synthetic<\/strong> relaxation experiment, take\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_0=10<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_\\infty=2<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.\nAt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>\nthe prediction is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><mo>+<\/mo><mn>8<\/mn><mi>/<\/mi><mi>e<\/mi><mo>≈<\/mo><mn>4.943<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2+8/e\\approx4.943<\/annotation><\/semantics><\/math>.\nAn independent observation could test this numerical prediction. The\nobservation window, sensor precision and criteria for notable\ndiscrepancies should be specified before collecting data. The figure\nshows the model only.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_178_EN.svg\"\nalt=\"Exponential curve from ten toward equilibrium value two, with time constant marked at three seconds.\" />\n<figcaption aria-hidden=\"true\">Exponential curve from ten toward\nequilibrium value two, with time constant marked at three\nseconds.<\/figcaption>\n<\/figure>\n<p><em>Original analytical model diagram with synthetic\nparameters.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">What is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y(0)<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Find the half-life for\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Why does a single discrepant observation not immediately refute\nevery version of the model?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mo>+<\/mo><mn>8<\/mn><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=2+8=10<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo>≈<\/mo><mn>2.079<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_{1/2}=3\\ln2\\approx2.079\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Measurement uncertainty, parameter errors and model alternatives\nmust be examined separately.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>Multiple timescales, temperature-dependent rates, drift and\nperturbations can violate the single-exponential approximation. Fitting\nthe same data does not constitute an independent prediction; agreement\ndoes not establish a unique physical mechanism.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>The next step examines how calibration maps a measured signal to a\nphysical quantity. <a href=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L2&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next\nlesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L1 – Research Questions, Hypotheses and Testable Model Predictions · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L1 – Research Questions, Hypotheses and Testable Model Predictions · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M43-L2 – Measurement Chains, Calibration and Systematic Deviations<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M32: instrumentation and calibration;\nM43-L1: model predictions.<\/p>\n<p><strong>Learning objective:<\/strong> Invert a linear sensor\ncalibration and separate the impact of an offset.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>Between a physical quantity and a reported number lie the sensor,\nelectronics, digitization, calibration and data processing. The\nmeasurement chain affects the result even when readings scatter very\nlittle. A stable unknown offset can produce high precision but poor\ntrueness. Calibration references and operating conditions therefore\nrequire documentation.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>A linear sensor is described by\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mi>a<\/mi><mi>T<\/mi><mo>+<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">U=aT+b<\/annotation><\/semantics><\/math>.\nWith known slope\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a\\ne0<\/annotation><\/semantics><\/math>\nand offset\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>,\ninversion gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>U<\/mi><mo>−<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=(U-b)/a<\/annotation><\/semantics><\/math>.\nIf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>\nis uncertain, its contribution to standard uncertainty follows from\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>T<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>b<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial T/\\partial b=-1/a<\/annotation><\/semantics><\/math>\nin the linear approximation. A full uncertainty budget also includes\nsignal uncertainty, covariances and slope uncertainty.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mfrac><mrow><mi>U<\/mi><mo>−<\/mo><mi>b<\/mi><\/mrow><mi>a<\/mi><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mfrac><mrow><mi>∂<\/mi><mi>T<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>b<\/mi><\/mrow><\/mfrac><mo>=<\/mo><mi>−<\/mi><mfrac><mn>1<\/mn><mi>a<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=\\frac{U-b}{a},\\qquad \\frac{\\partial T}{\\partial b}=-\\frac1a.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>A <strong>synthetic<\/strong> sensor has\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">K<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">a=2\\,\\mathrm{mV/K}<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>=<\/mo><mn>0.5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">b=0.5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>.\nFor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>10.5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">U=10.5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>,\nthe inferred value is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=5\\,\\mathrm K<\/annotation><\/semantics><\/math>.\nIgnoring the offset would incorrectly yield\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5.25<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">5.25\\,\\mathrm K<\/annotation><\/semantics><\/math>.\nPoints in the chart are generated from the calibration model, not\nmeasured on an actual instrument.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_165_EN.svg\"\nalt=\"Linear sensor response with an offset and a synthetic signal point at five kelvin.\" />\n<figcaption aria-hidden=\"true\">Linear sensor response with an offset and\na synthetic signal point at five kelvin.<\/figcaption>\n<\/figure>\n<p><em>Original schematic calibration chart.<\/em><\/p>\n<p>Not an instrument specification.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">What\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nfollows from\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>6.5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">U=6.5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">What is the bias if\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>\nis ignored?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">What is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>∂<\/mi><mi>T<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>b<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\partial T/\\partial b|<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">K<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{K/mV}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>6.5<\/mn><mo>−<\/mo><mn>0.5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=(6.5-0.5)/2=3\\,\\mathrm K<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5.25<\/mn><mo>−<\/mo><mn>5<\/mn><mo>=<\/mo><mn>0.25<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">5.25-5=0.25\\,\\mathrm K<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0.5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">K<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1/2=0.5\\,\\mathrm{K/mV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>Linear calibration is valid only over its verified range and\nsufficiently stable conditions. Hysteresis, ageing, nonlinearity and\nuncertain reference values require further tests. A numerically\nsubtracted offset is not automatically known exactly.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>Calibration prepares meaningful group comparisons; allocation and\nblinding are addressed next. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L3&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next lesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L2 – Measurement Chains, Calibration and Systematic Deviations · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L2 – Measurement Chains, Calibration and Systematic Deviations · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M43-L3 – Control Experiments, Randomization and Blinded Analysis<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M32: experimental design; M43-L2:\nmeasurement chain.<\/p>\n<p><strong>Learning objective:<\/strong> Calculate a synthetic group\ndifference and critically assess its causal interpretation.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>Controls probe the apparatus, while random assignment tends to\nbalance known and unknown confounders in expectation across repeated\nstudies. Blinded analysis can reduce analyst expectation effects. These\ntechniques do not replace physical controls or adequate sample sizes.\nAnalysis choices should, where possible, be recorded before treatment\nlabels are revealed.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>A descriptive comparison uses the difference of group means\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=\\overline y_B-\\overline y_A<\/annotation><\/semantics><\/math>.\nThat number alone says nothing about uncertainty or causation. For\nindependent samples and an appropriate variance model, the standard\nerror of the difference also matters; randomization improves design\nbalance in expectation but does not guarantee identical groups in a\nfinite sample.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>G<\/mi><\/msub><mo>=<\/mo><mfrac><mn>1<\/mn><msub><mi>n<\/mi><mi>G<\/mi><\/msub><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><msub><mi>n<\/mi><mi>G<\/mi><\/msub><\/munderover><msub><mi>y<\/mi><mrow><mi>G<\/mi><mi>i<\/mi><\/mrow><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=\\overline y_B-\\overline y_A,\\qquad \\overline y_G=\\frac{1}{n_G}\\sum_{i=1}^{n_G}y_{Gi}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>For a <strong>synthetic<\/strong> comparison, take\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>10<\/mn><mo>,<\/mo><mn>12<\/mn><mo>,<\/mo><mn>11<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=(10,12,11)<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>13<\/mn><mo>,<\/mo><mn>14<\/mn><mo>,<\/mo><mn>12<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B=(13,14,12)<\/annotation><\/semantics><\/math>\nin matching units. Then\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>=<\/mo><mn>11<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_A=11<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>=<\/mo><mn>13<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_B=13<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=2<\/annotation><\/semantics><\/math>.\nThe figure shows all six values to expose the small sample size. A\ncausal experimental interpretation requires appropriate allocation, a\ncontrolled measurement chain and explicit potential confounders.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_088_EN.svg\"\nalt=\"Six individual observations across two groups with means at eleven and thirteen.\" />\n<figcaption aria-hidden=\"true\">Six individual observations across two\ngroups with means at eleven and thirteen.<\/figcaption>\n<\/figure>\n<p><em>Original point plot with fabricated teaching values.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Find\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Δ<\/mi><annotation encoding=\"application/x-tex\">\\Delta<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>5<\/mn><mo>,<\/mo><mn>7<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=(5,7)<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><mo>,<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B=(8,10)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Why does a difference in means alone not establish causality?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">What should be fixed before unblinding?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>=<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_A=6<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>=<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_B=9<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Confounding, selection, calibration bias and random fluctuations\nremain unresolved.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">For example, exclusions, primary outcome and the analysis plan.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>With only three observations in each group, statistical uncertainty\nis substantial; the plotted points imply neither a confidence interval\nnor statistical significance. When randomization or blinding is\ninfeasible or inappropriate, limitations and alternatives must be\nreported.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>The next lesson connects multiple measured quantities to correlated\nuncertainty contributions. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L4&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next lesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L3 – Control Experiments, Randomization and Blinded Analysis · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L3 – Control Experiments, Randomization and Blinded Analysis · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M43-L4 – Uncertainty Budgets, Covariance and Error Propagation<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M32: uncertainty methods; M43-L2:\ncalibration; M43-L3: group comparisons.<\/p>\n<p><strong>Learning objective:<\/strong> Evaluate the impact of\ncorrelated inputs on the standard uncertainty of a derived quantity.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>Measurements can share calibration, environment or processing, so\ntheir uncertainty contributions are not independent. For a difference of\ntwo sensors subject to shared drift, positive correlation may cancel\npart of the common disturbance; for a sum it often reinforces it. A\ndefensible uncertainty budget lists components and their\ndependencies.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">z=x_1-x_2<\/annotation><\/semantics><\/math>,\nfirst-order propagation gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>u<\/mi><mi>z<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><msubsup><mi>u<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>u<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mo>−<\/mo><mn>2<\/mn><mi>ρ<\/mi><msub><mi>u<\/mi><mn>1<\/mn><\/msub><msub><mi>u<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">u_z^2=u_1^2+u_2^2-2\\rho u_1u_2<\/annotation><\/semantics><\/math>\nfor known standard uncertainties\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_i<\/annotation><\/semantics><\/math>\nand correlation coefficient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ρ<\/mi><annotation encoding=\"application/x-tex\">\\rho<\/annotation><\/semantics><\/math>.\nThis follows from\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mn>2<\/mn><mrow><mi mathvariant=\"normal\">C<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{Var}(X_1-X_2)=\\mathrm{Var}(X_1)+\\mathrm{Var}(X_2)-2\\mathrm{Cov}(X_1,X_2)<\/annotation><\/semantics><\/math>.\nFor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mo>≤<\/mo><mi>ρ<\/mi><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1\\le\\rho\\le1<\/annotation><\/semantics><\/math>,\nthe resulting variance is nonnegative for consistent inputs.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><msubsup><mi>u<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>u<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mo>−<\/mo><mn>2<\/mn><mi>ρ<\/mi><msub><mi>u<\/mi><mn>1<\/mn><\/msub><msub><mi>u<\/mi><mn>2<\/mn><\/msub><\/mrow><\/msqrt><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>z<\/mi><mo>=<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mn>2<\/mn><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">u_z=\\sqrt{u_1^2+u_2^2-2\\rho u_1u_2},\\qquad z=x_1-x_2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>For <strong>synthetic<\/strong> inputs with\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>0.2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_1=0.2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0.3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_2=0.3<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0.5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0.5<\/annotation><\/semantics><\/math>,\nthe combined uncertainty is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mn>0.04<\/mn><mo>+<\/mo><mn>0.09<\/mn><mo>−<\/mo><mn>0.06<\/mn><\/mrow><\/msqrt><mo>=<\/mo><msqrt><mn>0.07<\/mn><\/msqrt><mo>≈<\/mo><mn>0.265<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_z=\\sqrt{0.04+0.09-0.06}=\\sqrt{0.07}\\approx0.265<\/annotation><\/semantics><\/math>.\nFor independent inputs\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0<\/annotation><\/semantics><\/math>),\nit would be\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mn>0.13<\/mn><\/msqrt><mo>≈<\/mo><mn>0.361<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt{0.13}\\approx0.361<\/annotation><\/semantics><\/math>.\nThe chart shows continuous dependence on correlation; it is not a\ncorrelation function estimated from data.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_052_EN.svg\"\nalt=\"Standard uncertainty of a sensor difference versus correlation coefficient.\" />\n<figcaption aria-hidden=\"true\">Standard uncertainty of a sensor\ndifference versus correlation coefficient.<\/figcaption>\n<\/figure>\n<p><em>Original curve from the analytical covariance formula with\nsynthetic uncertainties.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Compute\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>z<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_z<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Compute\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>z<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_z<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=-1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Can correlation always be ignored for sensors with a shared\ncalibration?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0.3<\/mn><mo>−<\/mo><mn>0.2<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>0.1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|0.3-0.2|=0.1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.3<\/mn><mo>+<\/mo><mn>0.2<\/mn><mo>=<\/mo><mn>0.5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0.3+0.2=0.5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">No; shared influences can materially change the uncertainty\nbudget.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>For a linear difference the variance expression is exact. For general\nnonlinear functions the GUM linear approximation requires suitable local\nconditions; strongly nonlinear models may need Monte Carlo or other\nmethods. The value of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ρ<\/mi><annotation encoding=\"application/x-tex\">\\rho<\/annotation><\/semantics><\/math>\nmust be justified, never chosen merely for a favorable result.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>Uncertainty describes how well an estimated quantity is known. Next\ncomes the question of whether the observations can identify the model\nparameters at all. <a href=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L5&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next\nlesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L4 – Uncertainty Budgets, Covariance and Error Propagation · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L4 – Uncertainty Budgets, Covariance and Error Propagation · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M43-L5 – Parameter Sensitivity, Identifiability and Measurement Times<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M31: inverse problems; M43-L1:\nrelaxation model; M43-L4: uncertainty budget.<\/p>\n<p><strong>Learning objective:<\/strong> Explain why some parameters\ncannot be identified from measurements at a single time.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>A model may fit the observations well while its parameters remain\nambiguous. <strong>Identifiability<\/strong> asks whether different\nparameter values produce distinguishable predictions at all. Weak\nsensitivity makes estimation noise-sensitive, while identical\npredictions imply structural non-identifiability. Measurement times\nshould be chosen to separate the signatures of different parameters.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>;<\/mo><mi>A<\/mi><mo>,<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>A<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(t;A,k)=A e^{-kt}<\/annotation><\/semantics><\/math>\nwith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A&gt;0<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k&gt;0<\/annotation><\/semantics><\/math>,\nthe sensitivities are\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>A<\/mi><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial A=e^{-kt}<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>k<\/mi><mo>=<\/mo><mi>−<\/mi><mi>A<\/mi><mi>t<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial k=-At e^{-kt}<\/annotation><\/semantics><\/math>.\nAt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>,\nthe signal depends on\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nalone and has zero sensitivity to\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>.\nTwo noiseless measurements at\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t_0=0<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t_1&gt;0<\/annotation><\/semantics><\/math>\nidentify\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=y(0)<\/annotation><\/semantics><\/math>\nand then\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>/<\/mi><msub><mi>t<\/mi><mn>1<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">k=-\\ln[y(t_1)/A]/t_1<\/annotation><\/semantics><\/math>,\nprovided\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>&lt;<\/mo><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0&lt;y(t_1)&lt;A<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>∂<\/mi><mi>y<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>A<\/mi><\/mrow><\/mfrac><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mfrac><mrow><mi>∂<\/mi><mi>y<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>k<\/mi><\/mrow><\/mfrac><mo>=<\/mo><mi>−<\/mi><mi>A<\/mi><mi>t<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\frac{\\partial y}{\\partial A}=e^{-kt},\\qquad \\frac{\\partial y}{\\partial k}=-At e^{-kt}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>In a <strong>synthetic<\/strong> model set\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A=8<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0.25<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k=0.25\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>.\nThen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=8<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>0.5<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>4.852<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(2\\,\\mathrm{s})=8e^{-0.5}\\approx4.852<\/annotation><\/semantics><\/math>.\nThe two plotted points suffice to determine both parameters in this\nidealized model. With measurements only at\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\ncan take any value and is therefore unidentifiable.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_263_EN.svg\"\nalt=\"Exponential decay with observations at zero and two seconds; no sensitivity to k at time zero.\" />\n<figcaption aria-hidden=\"true\">Exponential decay with observations at\nzero and two seconds; no sensitivity to k at time zero.<\/figcaption>\n<\/figure>\n<p><em>Original analytical model curve, not experimental\nmeasurement.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">What is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>k<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial k<\/annotation><\/semantics><\/math>\nat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Why does a second measurement time improve estimation?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Find\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\nfrom\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A=8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=2\\,\\mathrm s<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>0.5<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(2)=8e^{-0.5}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>,\nregardless of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">A later observation depends on the decay rate, while\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>\nisolates amplitude.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0.5<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0.25<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k=0.5/2=0.25\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>Noise, unknown background, finite resolution and poorly chosen\nmeasurement times can strongly limit practical identifiability.\nParameter correlations and the local Jacobian matter in larger models.\nTwo observations are not a robust experimental design.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>After estimation, the next question is whether the residuals agree\nwith the assumed noise model. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L6&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next lesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L5 – Parameter Sensitivity, Identifiability and Measurement Times · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L5 – Parameter Sensitivity, Identifiability and Measurement Times · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M43-L6 – Residuals, Weighted Chi-Square and Model Adequacy<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M16: statistics; M31: validation;\nM43-L5: identifiability.<\/p>\n<p><strong>Learning objective:<\/strong> Compute standardized residuals\nand interpret a weighted fit metric under its assumptions.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>An attractive curve is not a sufficient model check.\nObservation-minus-model residuals must be compared with measurement\nprecision and possible dependence. For uncorrelated observations with\nknown standard deviations, a weighted sum of squares is useful\ndiagnostic information. A reduced value near one is only a benchmark\nunder appropriate model assumptions and does not prove the physics\ncorrect.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>For observations\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>y<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">y_i<\/annotation><\/semantics><\/math>,\npredictions\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>θ<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f_i(\\hat\\theta)<\/annotation><\/semantics><\/math>\nand known\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_i&gt;0<\/annotation><\/semantics><\/math>,\nthe weighted statistic is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=\\sum_i[(y_i-f_i)/\\sigma_i]^2<\/annotation><\/semantics><\/math>.\nWhen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nindependent parameters are fitted to the same\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nobservations and regularity conditions hold, the nominal residual\ndegrees of freedom are often\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\nu=n-p<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mi>ν<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2_\\mathrm{red}=\\chi^2/\\nu<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu&gt;0<\/annotation><\/semantics><\/math>.\nA chi-square reference distribution requires further assumptions,\nincluding an appropriate error covariance and approximately Gaussian\nmeasurement errors.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>θ<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><mfrac><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mrow><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=\\sum_{i=1}^n\\left(\\frac{y_i-f_i(\\hat\\theta)}{\\sigma_i}\\right)^2,\\qquad \\chi^2_{\\mathrm{red}}=\\frac{\\chi^2}{n-p}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>A <strong>synthetic<\/strong> three-point example uses\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y=(2,4,5)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2.1<\/mn><mo>,<\/mo><mn>3.8<\/mn><mo>,<\/mo><mn>5.1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f=(2.1,3.8,5.1)<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.1<\/mn><mo>,<\/mo><mn>0.2<\/mn><mo>,<\/mo><mn>0.1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\sigma=(0.1,0.2,0.1)<\/annotation><\/semantics><\/math>.\nStandardized residuals are\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,1,-1)<\/annotation><\/semantics><\/math>,\nyielding\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=3<\/annotation><\/semantics><\/math>.\nIf exactly one independently identifiable parameter was estimated from\nthese three readings\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=1<\/annotation><\/semantics><\/math>),\nthen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu=2<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><mn>1.5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2_\\mathrm{red}=1.5<\/annotation><\/semantics><\/math>.\nThe diagram only displays standardized residuals; it does not establish\na formal p-value.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_318_EN.svg\"\nalt=\"Three standardized residuals with values minus one, plus one and minus one.\" />\n<figcaption aria-hidden=\"true\">Three standardized residuals with values\nminus one, plus one and minus one.<\/figcaption>\n<\/figure>\n<p><em>Original schematic residual plot from synthetic numbers.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">What is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\chi^2<\/annotation><\/semantics><\/math>\nfor standardized residuals\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,2,0)<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">How many nominal degrees of freedom result for\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=10<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=3<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Why can an unusually small chi-square also deserve scrutiny?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>1<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>2<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>0<\/mn><mn>2<\/mn><\/msup><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1^2+2^2+0^2=5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mn>10<\/mn><mo>−<\/mo><mn>3<\/mn><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu=10-3=7<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Check overestimated\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\sigma_i<\/annotation><\/semantics><\/math>,\ncorrelations or excessive model flexibility.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>Correlated errors require the full covariance matrix; diagonally\nweighted residuals may be misleading. Small samples, nonlinear fits,\nunknown variances and boundary parameters can invalidate naive\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n-p<\/annotation><\/semantics><\/math>\ninterpretations. Model adequacy should also be assessed using\nindependent data.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>The final lesson integrates design, model checking and reporting into\nan auditable workflow. <a href=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L7&amp;syslang=en&amp;doclang=en&amp;theme=light\">Next\nlesson<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://itl.nist.gov/div898/handbook/pmd/section1/pmd143.htm\">NIST – Weighted Least Squares Regression<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L6 – Residuals, Weighted Chi-Square and Model Adequacy · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.itl.nist.gov/div898/handbook/pmd/section4/pmd452.htm\">NIST – Accounting for Non-Constant Variation Across the Data<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L6 – Residuals, Weighted Chi-Square and Model Adequacy · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L6 – Residuals, Weighted Chi-Square and Model Adequacy · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_en:M43-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M43-L7 – Research Capstone: External Validation and Transparent Reporting<\/h1>\n<p><strong>Course area:<\/strong> M43 – Master: Model Assessment and Scientific Research Practice<\/p>\n<p><strong>Level:<\/strong> Master · advanced specialization<\/p>\n<p><strong>Prerequisites:<\/strong> M43-L1–L6: prediction, calibration,\ndesign, uncertainty and model assessment.<\/p>\n<p><strong>Learning objective:<\/strong> Complete a small physical-model\nvalidation on pre-separated test data and document the limits of the\nconclusion.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Guiding question and context<\/h2>\n<p>A research report turns a sequence of decisions into an auditable\nresult: question, assumptions, measurement protocol, raw data,\ncalibration, processing, code version, uncertainty budget, model checks\nand justified conclusions. <strong>External validation<\/strong> here\nmeans that the evaluation data were not used for fitting the model or\nchoosing its parameters afterward. Transparent reporting includes\nnegative results, alternative models and deviations from the original\nplan.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physical model and derivation<\/h2>\n<p>For a predesignated holdout set, a simple error metric in the\noriginal measurement units is the mean absolute error:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><msup><mi>n<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=n^{-1}\\sum_i|y_i-\\hat y_i|<\/annotation><\/semantics><\/math>.\nUnlike a training residual, it estimates prediction error outside\nfitting if the split was genuinely independent. It does not by itself\nreveal the error distribution, measurement uncertainty, bias or\ngeneralization to new regimes.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mfrac><mn>1<\/mn><mi>n<\/mi><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=\\frac{1}{n}\\sum_{i=1}^{n}|y_i-\\widehat y_i|.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Worked example and teaching figure<\/h2>\n<p>Four <strong>synthetic, prespecified holdout<\/strong> readings are\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>3<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y=(2,3,4,5)<\/annotation><\/semantics><\/math>\nunits, while the fixed model predicts\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2.2<\/mn><mo>,<\/mo><mn>2.9<\/mn><mo>,<\/mo><mn>4.1<\/mn><mo>,<\/mo><mn>4.8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\hat y=(2.2,2.9,4.1,4.8)<\/annotation><\/semantics><\/math>.\nAbsolute errors are\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.2<\/mn><mo>,<\/mo><mn>0.1<\/mn><mo>,<\/mo><mn>0.1<\/mn><mo>,<\/mo><mn>0.2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0.2,0.1,0.1,0.2)<\/annotation><\/semantics><\/math>,\ngiving\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mn>0.15<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=0.15<\/annotation><\/semantics><\/math>\nunits. The scatter plot compares prediction and observation against the\nideal diagonal. Both the data and the claimed holdout independence are\n<strong>teaching assumptions<\/strong>, not an audited research\nstudy.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-en/media/img/U_PHY_242_EN.svg\"\nalt=\"Four artificial prediction-versus-observation points with the ideal identity line.\" />\n<figcaption aria-hidden=\"true\">Four artificial\nprediction-versus-observation points with the ideal identity\nline.<\/figcaption>\n<\/figure>\n<p><em>Original validation sketch with entirely synthetic data.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Calculate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}<\/annotation><\/semantics><\/math>\nfor absolute errors\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.2<\/mn><mo>,<\/mo><mn>0.4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0.2,0.4)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Why is adjusting a model after seeing test errors problematic?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">What must accompany a reproducible final report?<\/div><\/li>\n<\/ol>\n<h3 id=\"solutions\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Solutions<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mn>0.3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=0.3<\/annotation><\/semantics><\/math>\nin the measurement units.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">The test set then influences model selection, so the reported metric\nis no longer an independent evaluation.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Protocol, raw data or documented access conditions, calibration,\ncode/environment, uncertainties, deviations and sources.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Limits of validity and quality<\/h2>\n<p>Four artificial points and one error metric cannot validate a\nresearch program. Errors may be correlated; a defensible claim needs\nuncertainty analysis, physical scope, safety and ethics review and\npossibly independent replication. FAIR principles require documented\naccessibility, not universal public release of all raw data.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Summary and outlook<\/h2>\n<p>The final lesson connects model predictions, measurement protocols,\nindependently held-out test data and the limits of validation.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources (external)<\/h2>\n<h3 id=\"references\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>References<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L7 – Research Capstone: External Validation and Transparent Reporting · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L7 – Research Capstone: External Validation and Transparent Reporting · Last accessed: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Subject relevance to lesson: M43-L7 – Research Capstone: External Validation and Transparent Reporting · Last accessed: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
